import { Select } from "@components/select";
import { clsx } from "clsx";

import { useList } from "../hooks/use-list";
import { type ListPageSizeSelectProps } from "../list.types";
import { ListClasses } from "../list.styles";

export const ListPageSizeSelect = ({
  options,
  className,
  renderLabel = (pageSize) => `Show ${pageSize}`,
  width,
  ...props
}: ListPageSizeSelectProps) => {
  const { state, setPageSize } = useList();
  const { pagination } = state;

  return (
    <Select
      className={clsx(ListClasses.pageSizeSelect, className)}
      showSelectedIndicator={false}
      style={{ width }}
      value={pagination.pageSize.toString()}
      onValueChange={(value) => {
        setPageSize(Number(value));
      }}
      {...props}
    >
      <Select.Trigger aria-label={props["aria-label"] || "Select page size"}>
        <Select.Value />
        <Select.Icon />
      </Select.Trigger>
      <Select.Content>
        {options?.map((pageSize) => (
          <Select.Item
            key={pageSize}
            data-testid={`page-size-${pageSize}`}
            value={pageSize.toString()}
          >
            {renderLabel(pageSize)}
          </Select.Item>
        ))}
      </Select.Content>
    </Select>
  );
};

ListPageSizeSelect.displayName = "List.PageSizeSelect";
